{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= n <= 2 * 10^5",
      "description": "The number of bracket types is between 1 and 2 * 10^5, inclusive."
    },
    {
      "id": "P2",
      "expression": "Each integer 1,-1,2,-2,...,n,-n appears exactly once as a_i and exactly once as b_i",
      "description": "Each integer appears exactly once on the front and exactly once on the back of some card."
    },
    {
      "id": "P3",
      "expression": "-n <= a_i, b_i <= n and a_i != 0 and b_i != 0",
      "description": "The numbers on the front and back of each card are integers between -n and n, excluding zero."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "output == 'YES' or output == 'NO'",
      "description": "The output is either 'YES' if it's possible to reorder the cards to satisfy the condition, or 'NO' if it's impossible."
    },
    {
      "id": "Q2",
      "expression": "output == 'YES' ==> (exists permutation of cards such that front_sequence and back_sequence are both balanced)",
      "description": "If the output is 'YES', there exists a permutation of the cards such that the sequence of front numbers and the sequence of back numbers are both balanced."
    },
    {
      "id": "Q3",
      "expression": "output == 'NO' ==> (for all permutations of cards, front_sequence and back_sequence are not both balanced)",
      "description": "If the output is 'NO', no permutation of the cards can result in both the front and back sequences being balanced."
    }
  ],
  "invariants": [
    {
      "id": "I1",
      "expression": "front_sequence == sorted(front_sequence)",
      "description": "The sequence of front numbers is sorted in ascending order."
    },
    {
      "id": "I2",
      "expression": "back_sequence == sorted(back_sequence)",
      "description": "The sequence of back numbers is sorted in ascending order."
    }
  ]
}
